/**
 * @ingroup iface_xx_text_input_v3
 * Sends an enter event to the client owning the resource.
 * @param resource_ The client's resource
 */
static inline void
xx_text_input_v3_send_enter(struct wl_resource *resource_, struct wl_resource *surface)
{
	wl_resource_post_event(resource_, XX_TEXT_INPUT_V3_ENTER, surface);
}

